ALTER TABLE vault_core_pertanyaan_wajib_only
 ADD COLUMN IF NOT EXISTS field_key TEXT,
 ADD COLUMN IF NOT EXISTS input_type TEXT NOT NULL DEFAULT 'text',
 ADD COLUMN IF NOT EXISTS field_options JSONB NOT NULL DEFAULT '[]'::jsonb,
 ADD COLUMN IF NOT EXISTS field_placeholder TEXT NOT NULL DEFAULT '',
 ADD COLUMN IF NOT EXISTS field_group TEXT NOT NULL DEFAULT 'Deskripsi Produk',
 ADD COLUMN IF NOT EXISTS field_max_length INTEGER NOT NULL DEFAULT 160,
 ADD COLUMN IF NOT EXISTS is_public BOOLEAN NOT NULL DEFAULT TRUE;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='vc_question_input_type_check' AND conrelid='public.vault_core_pertanyaan_wajib_only'::regclass) THEN ALTER TABLE vault_core_pertanyaan_wajib_only ADD CONSTRAINT vc_question_input_type_check CHECK(input_type IN ('text','number','select','textarea')); END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='vc_question_field_options_array_check' AND conrelid='public.vault_core_pertanyaan_wajib_only'::regclass) THEN ALTER TABLE vault_core_pertanyaan_wajib_only ADD CONSTRAINT vc_question_field_options_array_check CHECK(jsonb_typeof(field_options)='array'); END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='vc_question_field_max_length_check' AND conrelid='public.vault_core_pertanyaan_wajib_only'::regclass) THEN ALTER TABLE vault_core_pertanyaan_wajib_only ADD CONSTRAINT vc_question_field_max_length_check CHECK(field_max_length BETWEEN 1 AND 4000); END IF;
END $$;
