ON CONFLICT(pertanyaan_id) DO UPDATE SET variant_id=EXCLUDED.variant_id,urutan_pertanyaan=EXCLUDED.urutan_pertanyaan,pertanyaan_wajib=EXCLUDED.pertanyaan_wajib,sifat_item='WAJIB',field_key=EXCLUDED.field_key,input_type=EXCLUDED.input_type,field_options=EXCLUDED.field_options,field_placeholder=EXCLUDED.field_placeholder,field_group=EXCLUDED.field_group,field_max_length=EXCLUDED.field_max_length,is_public=EXCLUDED.is_public;
ALTER TABLE vault_core_pertanyaan_wajib_only ALTER COLUMN field_key SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS ux_vc_listing_field_key ON vault_core_pertanyaan_wajib_only(variant_id,field_key);
CREATE INDEX IF NOT EXISTS idx_vc_listing_fields_variant_order ON vault_core_pertanyaan_wajib_only(variant_id,urutan_pertanyaan);
UPDATE vault_core_varian_wajib SET status_audit='PUBLIC_LISTING_FIELDS_READY',temuan_audit='Master field ini berisi spesifikasi produk yang diisi Owner dan ditampilkan pada halaman penjualan. Verifikasi hak, data akses, bukti kepemilikan, dan fulfillment dikelola pada alur internal terpisah.' WHERE variant_id BETWEEN 1 AND 12;
CREATE OR REPLACE VIEW vw_vault_core_audit_pertanyaan_wajib_owner AS
SELECT v.variant_id,v.nama_game,v.kategori_produk,v.jenis_varian,v.status_audit,COUNT(q.pertanyaan_id) AS jumlah_pertanyaan_wajib,STRING_AGG(q.urutan_pertanyaan::text||'. '||q.pertanyaan_wajib,' | ' ORDER BY q.urutan_pertanyaan) AS daftar_pertanyaan_wajib
FROM vault_core_varian_wajib v LEFT JOIN vault_core_pertanyaan_wajib_only q ON q.variant_id=v.variant_id GROUP BY v.variant_id,v.nama_game,v.kategori_produk,v.jenis_varian,v.status_audit;